import 'package:flutter/foundation.dart';

import '../platform/sound.dart';
import 'rules/models.dart';

export '../platform/sound.dart' show SoundLoop;

/// The game's chiptune sound effects and background music, generated by
/// `tool/sounds/generate.py`. Off until the player turns it on in the
/// account menu; the device remembers it.
class GameSound {
  GameSound._(this._output) : enabled = ValueNotifier(_output.savedOn);

  /// The one for the whole app.
  static final instance = GameSound._(SoundOutput());

  final SoundOutput _output;

  /// Whether sound is on.
  final ValueNotifier<bool> enabled;

  /// The sounds played, newest last (with sound on), for tests.
  @visibleForTesting
  final played = <String>[];

  static const _musicVolume = 0.35;
  static const _duckedVolume = 0.08;

  SoundLoop? _music;
  int _ducks = 0;

  void toggle() => setEnabled(!enabled.value);

  void setEnabled(bool on) {
    if (on) _output.wake();
    enabled.value = on;
    _output.save(on);
    startMusic();
  }

  /// Starts the background music if sound is on (stops it if off).
  void startMusic() {
    if (!enabled.value) {
      _music?.stop();
      _music = null;
    } else {
      _music ??= _output.loop('music.wav', volume: _ducks > 0 ? _duckedVolume : _musicVolume);
    }
  }

  /// Turns the music down while a screen with sounds of its own is open,
  /// until [unduck].
  void duck() {
    _ducks++;
    _music?.volume = _duckedVolume;
  }

  void unduck() {
    if (_ducks > 0) _ducks--;
    if (_ducks == 0) _music?.volume = _musicVolume;
  }

  /// Plays [file] of `assets/sounds/` once, if sound is on.
  void play(String file, {double volume = 1}) {
    if (!enabled.value) return;
    played.add(file);
    _output.play(file, volume: volume);
  }

  /// Plays [file] over and over if sound is on, until stopped.
  SoundLoop? loop(String file, {double volume = 1}) {
    if (!enabled.value) return null;
    played.add(file);
    return _output.loop(file, volume: volume);
  }

  // The drawing step.
  void timerTick() => play('timer_tick.mp3', volume: 0.7);
  void timerFinal() => play('timer_final.mp3');
  void timeUp() => play('time_up.mp3');
  void drawingSaved() => play('drawing_saved.mp3');

  // Boosting.
  void starDrop() => play('star_drop.mp3');

  // Fights.
  void fightResult({required bool won}) => play(won ? 'fight_win.mp3' : 'fight_lose.mp3');

  // The summon, for the rarest card in the box.
  void boxLands() => play('summon_land.mp3');
  SoundLoop? tapeTearing() => loop('summon_tape.wav', volume: 0);
  void tapeCut() => play('summon_cut.mp3');
  void boxShakes(Rarity rarity) => play('summon_shake_${rarity.name}.mp3');
  void boxOpens(Rarity rarity) => play('summon_open_${rarity.name}.mp3');
  void cardRises(Rarity rarity) => play('summon_beam_${rarity.name}.mp3', volume: 0.8);
  void cardFlips() => play('summon_flip.mp3', volume: 0.8);
  void cardRevealed(Rarity rarity) => play('summon_reveal_${rarity.name}.mp3');
}

/// The app's [GameSound].
GameSound get sound => GameSound.instance;
